import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test("A certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review whose insurance certificate expires today. The server dates
  // "today" in UTC, so the expiry date is built the same way.
  const today = new Date().toISOString().slice(0, 10);
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await factory.upload(vendor.id, "contract", "contract.txt", "member");
  const certificate = Buffer.from(
    ["Insurer: Harbor Mutual", "Policy Number: HM-EXPIRES-TODAY", "Coverage Amount: $2,000,000", `Expiry Date: ${today}`, ""].join("\n"),
  );
  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: { kind: "insurance_certificate", file: { name: "insurance_certificate.txt", mimeType: "text/plain", buffer: certificate } },
  });
  const insurance = await expectStatus<Document>(upload, 201);
  await expect
    .poll(
      async () => {
        const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
        return documents.map((d) => d.status).sort();
      },
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(submitted.status, "vendor is in review").toBe("in_review");
  const pending = await factory.extraction(insurance.id);
  expect(pending.status, "insurance extraction awaits review").toBe("pending_review");

  // Act: a reviewer approves the insurance certificate extraction.
  const reviewer = await apiAs("reviewer");
  const response = await reviewer.post(`/api/extractions/${pending.id}/decision`, { data: { decision: "approve" } });
  const decided = await expectStatus<Extraction>(response, 200);

  // Assert: the response and the stored extraction both show the approval.
  expect(decided.status).toBe("approved");
  const stored = await factory.extraction(insurance.id);
  expect(stored.status).toBe("approved");
});
